static void pretty_number(const char *s,uint16_t c){int x=27;while(*s){int n=*s++-'0';if(n<0||n>9){rect(x,37,19,4,c);x+=25;continue;}for(int y=0;y<60;y++)for(int i=0;i<60;i++)if(number_alpha[n][y*60+i])pixel(x+i,12+y,c,number_alpha[n][y*60+i]);x+=number_advance[n];}}
static void rounded(float x,float y,float w,float h,float radius,uint16_t c){
 float cx=x+w*.5f,cy=y+h*.5f;
 for(int j=(int)y;j<(int)(y+h);j++)for(int i=(int)x;i<(int)(x+w);i++){
  float qx=fabsf(i+.5f-cx)-(w*.5f-radius),qy=fabsf(j+.5f-cy)-(h*.5f-radius);
  float distance=hypotf(fmaxf(qx,0),fmaxf(qy,0))+fminf(fmaxf(qx,qy),0)-radius;
  unsigned a=(unsigned)(255*fminf(1,fmaxf(0,.5f-distance)));
  pixel(i+(int)content_dx,j,c,a);
 }}
static void segmented_bar(float x,float y,int count,float level,uint16_t c){
 const float w=24,h=134,gap=4,sh=(h-gap*(count-1))/count;
 rounded(x-6,y-7,w+12,h+14,17,c);
 rounded(x-4,y-5,w+8,h+10,15,color(20,25,28));
 for(int i=0;i<count;i++){
  float top=y+h-(i+1)*sh-i*gap;
  rounded(x,top,w,sh,fminf(5,sh*.5f),color(53,65,72));
  float amount=fminf(1,fmaxf(0,level*count-i));
  if(amount>0)rounded(x,top+sh*(1-amount),w,sh*amount,fminf(5,sh*amount*.5f),c);
 }
}
static void icon_stroke(float ax,float ay,float bx,float by,float thickness,uint16_t c){
 float dx=bx-ax,dy=by-ay,len=dx*dx+dy*dy;
 for(int y=floorf(fminf(ay,by)-thickness);y<=ceilf(fmaxf(ay,by)+thickness);y++)
 for(int x=floorf(fminf(ax,bx)-thickness);x<=ceilf(fmaxf(ax,bx)+thickness);x++){
 float t=len?fminf(1,fmaxf(0,((x+.5f-ax)*dx+(y+.5f-ay)*dy)/len)):0;
 float d=hypotf(x+.5f-ax-t*dx,y+.5f-ay-t*dy);
 float a=fminf(1,fmaxf(0,thickness*.5f+.5f-d));if(a>0)pixel(x+(int)content_dx,y,c,lroundf(a*255));}}
static void device_icon(int kind,float cx,float y,uint16_t c){
 if(!kind){icon_stroke(cx,y+5,cx,y+17,10,c);
 icon_stroke(cx-10,y+13,cx-10,y+20,2.3f,c);icon_stroke(cx+10,y+13,cx+10,y+20,2.3f,c);
 icon_stroke(cx-10,y+20,cx-6,y+25,2.3f,c);icon_stroke(cx-6,y+25,cx+6,y+25,2.3f,c);icon_stroke(cx+6,y+25,cx+10,y+20,2.3f,c);
 icon_stroke(cx,y+25,cx,y+30,2.3f,c);icon_stroke(cx-6,y+30,cx+6,y+30,2.3f,c);
 }else{icon_stroke(cx,y+9,cx,y+24,20,c);icon_stroke(cx,y+9,cx,y+24,16,color(0,0,0));
 dot(cx,y+7,2,c);icon_stroke(cx-4,y+18,cx+4,y+18,2,c);icon_stroke(cx,y+14,cx,y+22,2,c);}}
static void coding_mark(void){uint16_t c=color(141,170,170);
 icon_stroke(408,32,419,41,3,c);icon_stroke(419,41,408,50,3,c);icon_stroke(426,50,438,50,3,c);
}
