static void large_wrap(const char *s,int y,uint16_t c){int lines=y>=370?1:4;for(int line=0;line<lines&&*s;line++){char row[200];int n=0,w=0;while(*s){if(*s=='\n'){s++;break;}const char *p=s;uint32_t cp=next(&p);int cw=lroundf((glyph(cp)?glyph(cp)->advance:32)*34.f/30);if(w+cw>(y>=370?238:380))break;int len=p-s;if(n+len>180)break;memcpy(row+n,s,len);n+=len;s=p;w+=cw;}row[n]=0;if(line==lines-1&&*s){while(n&&large_width(row)>(y>=370?203:345)){do{n--;}while(n&&((unsigned char)row[n]&192)==128);row[n]=0;}strcat(row,"...");}large(row,y+line*40,c);}}
