  copy(p->id,sizeof p->id,v,"id");copy(p->label,sizeof p->label,v,"label");p->weekly=battery_number(cJSON_GetObjectItemCaseSensitive(v,"weekly_percent"),100);
  p->has_five_hour=cJSON_IsTrue(cJSON_GetObjectItemCaseSensitive(v,"five_hour_available"));p->five_hour=battery_number(cJSON_GetObjectItemCaseSensitive(v,"five_hour_percent"),100);
